DROP FUNCTION IF EXISTS create_category(text);
CREATE FUNCTION create_category(p_name text) RETURNS categories LANGUAGE sql AS $$ INSERT INTO categories (name) VALUES (p_name) RETURNING *; $$;
DROP FUNCTION IF EXISTS get_category(uuid);
CREATE FUNCTION get_category(p_id uuid) RETURNS SETOF categories LANGUAGE sql AS $$ SELECT * FROM categories WHERE id = p_id; $$;
DROP FUNCTION IF EXISTS update_category(uuid, text);
CREATE FUNCTION update_category(p_id uuid, p_name text) RETURNS categories LANGUAGE plpgsql AS $$ DECLARE r categories; BEGIN UPDATE categories SET name = p_name WHERE id = p_id RETURNING * INTO r; IF NOT FOUND THEN RAISE EXCEPTION 'category % not found', p_id USING ERRCODE = 'P0002'; END IF; RETURN r; END $$;
DROP FUNCTION IF EXISTS delete_category(uuid);
CREATE FUNCTION delete_category(p_id uuid) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN DELETE FROM categories WHERE id = p_id; RETURN FOUND; END $$;
DROP FUNCTION IF EXISTS list_categories();
CREATE FUNCTION list_categories() RETURNS SETOF categories LANGUAGE sql AS $$ SELECT * FROM categories ORDER BY id; $$;
