DROP FUNCTION IF EXISTS delete_product(uuid);
CREATE FUNCTION delete_product(p_id uuid) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN DELETE FROM products WHERE id = p_id; RETURN FOUND; END $$;
